import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.BS0bAV7E.js";const p=JSON.parse('{"title":"Contributing to Open Cube OS","description":"","frontmatter":{},"headers":[],"relativePath":"root/CONTRIBUTING.md","filePath":"root/CONTRIBUTING.md"}'),n={name:"root/CONTRIBUTING.md"};function i(r,e,l,d,c,h){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="contributing-to-open-cube-os" tabindex="-1">Contributing to Open Cube OS <a class="header-anchor" href="#contributing-to-open-cube-os" aria-label="Permalink to &quot;Contributing to Open Cube OS&quot;">​</a></h1><p>Thank you for your interest in contributing! Open Cube OS is a from-scratch x86_64 kernel, and every contribution - code, documentation, driver bring-up, bug reports - is welcome.</p><h2 id="ground-rules" tabindex="-1">Ground rules <a class="header-anchor" href="#ground-rules" aria-label="Permalink to &quot;Ground rules&quot;">​</a></h2><ol><li><p><strong>Kernel strings are ASCII English.</strong> Everything the system itself prints (command names, prompts, boot messages, help text) must stay plain ASCII. Non-ASCII text may appear in user data and in documentation, never in kernel-visible strings.</p></li><li><p><strong>The command surface only grows.</strong> A shell command that has shipped may be reworked internally, but its name and overall behaviour must stay; removals break the interface contract. Register new commands with <code>shell_register_command_ex()</code> and a work-package tag.</p></li><li><p><strong>Zero warnings.</strong> The build compiles with <code>-Wall -Wextra -Werror</code>. A change that introduces a warning is a broken change, on your machine and on CI.</p></li><li><p><strong>No stubs, no fake data.</strong> If a feature is partial, say so in the code and the docs - never paper over it. A driver that only probes and reports &quot;not supported on this machine&quot; is fine; a driver that pretends to work is not.</p></li><li><p><strong>Apache 2.0 everywhere.</strong> Every new source file starts with the SPDX header:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/* SPDX-License-Identifier: Apache-2.0 */</span></span>
<span class="line"><span>/* Copyright 2026 cubestudio-dev &lt;cubestudio@qq.com&gt; */</span></span></code></pre></div></li></ol><h2 id="development-flow" tabindex="-1">Development flow <a class="header-anchor" href="#development-flow" aria-label="Permalink to &quot;Development flow&quot;">​</a></h2><h3 id="_1-get-a-build-going" tabindex="-1">1. Get a build going <a class="header-anchor" href="#_1-get-a-build-going" aria-label="Permalink to &quot;1. Get a build going&quot;">​</a></h3><p>Follow <a href="./BUILDING.html">BUILDING.md</a>. The short version on Linux:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./build.sh iso          # kernel + bootable ISO</span></span>
<span class="line"><span>make test               # host-side unit tests</span></span></code></pre></div><p>You need <code>gcc, nasm, grub-mkimage, xorriso, mtools, python3, zip</code> (<code>tools/build.sh</code> checks and tells you the exact missing ones, or installs them with <code>--install</code>).</p><h3 id="_2-make-your-change" tabindex="-1">2. Make your change <a class="header-anchor" href="#_2-make-your-change" aria-label="Permalink to &quot;2. Make your change&quot;">​</a></h3><ul><li>Keep the change focused: one driver, one fix, one documentation chapter per pull request.</li><li>Every kernel source file carries the SPDX header - keep it.</li><li>New commands: register in the matching <code>shell/shell_cmds_*.c</code>, add the help line, and extend the regression expectations (see <code>tools/run_fix4_regression.py</code>, the command-count baseline).</li></ul><h3 id="_3-test-before-you-push" tabindex="-1">3. Test before you push <a class="header-anchor" href="#_3-test-before-you-push" aria-label="Permalink to &quot;3. Test before you push&quot;">​</a></h3><p>The minimum bar, all of it:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make kernel             # 0 errors, 0 warnings (-Werror enforced)</span></span>
<span class="line"><span>make test               # host unit suite (tools/run_host_tests.py)</span></span>
<span class="line"><span>make iso                # hybrid BIOS+UEFI ISO builds</span></span>
<span class="line"><span>make reproducible-check # two clean builds -&gt; byte-identical ELF</span></span></code></pre></div><p>Then boot it:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make run-bios   # or: qemu-system-x86_64 -cdrom build/opencube.iso</span></span>
<span class="line"><span>make run-uefi   # OVMF path</span></span></code></pre></div><p>If your change touches anything listed below, the matching deep test is also required:</p><table tabindex="0"><thead><tr><th>You touched...</th><th>Also run</th></tr></thead><tbody><tr><td>storage / filesystems</td><td><code>fstest</code>, <code>dhtest</code> in the guest</td></tr><tr><td>crypto / TLS / SSH</td><td><code>cryptotest</code> in the guest, HTTPS E2E</td></tr><tr><td>watchdog / klog / health</td><td><code>tools/wp12_watchdog_logging_e2e.py build/opencube.iso</code></td></tr><tr><td>the full boot path</td><td>the regression suite (<code>tools/run_fix4_regression.py</code>)</td></tr><tr><td>A/B slots or OTA</td><td><code>ab_partition_test</code>, OTA install test in the guest</td></tr></tbody></table><p>CI (<code>.github/workflows/build.yml</code>) runs the build, packaging, host tests and reproducibility gate on every PR - it must be green before merge.</p><h3 id="_4-commit-style" tabindex="-1">4. Commit style <a class="header-anchor" href="#_4-commit-style" aria-label="Permalink to &quot;4. Commit style&quot;">​</a></h3><ul><li>One commit per logical step; each commit message answers <em>what</em> and <em>why</em>, not just <em>what</em>.</li><li>Prefix with the area: <code>usb: ...</code>, <code>fs: fat32: ...</code>, <code>docs: ...</code>, <code>build: ...</code>.</li><li>If you fixed a tracked audit bug, reference its number (<code>BUG-0136</code>) in the message.</li></ul><h3 id="_5-pull-requests" tabindex="-1">5. Pull requests <a class="header-anchor" href="#_5-pull-requests" aria-label="Permalink to &quot;5. Pull requests&quot;">​</a></h3><ol><li>Fork or branch from <code>main</code>.</li><li>Push your branch, open the PR against <code>cubestudio-dev/OpenCubeOS</code>.</li><li>Fill in the checklist from the PR template: <ul><li>[ ] builds with 0 warnings (<code>-Wall -Wextra -Werror</code>)</li><li>[ ] host tests pass (<code>make test</code>)</li><li>[ ] booted in QEMU (BIOS and UEFI)</li><li>[ ] relevant deep tests pass (table above)</li><li>[ ] docs updated (manual pages under <code>docs/</code>, interface lists if the L1 surface changed)</li></ul></li><li>Expect review comments about edge cases, DMA bounds and error paths - that is normal for kernel code.</li></ol><h2 id="reporting-bugs" tabindex="-1">Reporting bugs <a class="header-anchor" href="#reporting-bugs" aria-label="Permalink to &quot;Reporting bugs&quot;">​</a></h2><p>Open an issue with:</p><ul><li>the build identifier from <code>uname -a</code> inside the guest,</li><li>the exact command sequence,</li><li>the serial log (<code>-serial file:log.txt</code> is your friend),</li><li>whether it reproduces on BIOS, UEFI, or both.</li></ul><p>Security-sensitive reports: see <code>SECURITY</code> notes in the README - do not open a public issue; email the maintainers instead.</p><h2 id="documentation-contributions" tabindex="-1">Documentation contributions <a class="header-anchor" href="#documentation-contributions" aria-label="Permalink to &quot;Documentation contributions&quot;">​</a></h2><p>The documentation tree under <code>docs/</code> is the product, not an afterthought. If you add a command or an interface, the matching manual/reference page must land in the same PR. Reference pages are generated from the real tree (<code>make api-docs</code>) - do not hand-edit generated tables.</p><h2 id="licensing" tabindex="-1">Licensing <a class="header-anchor" href="#licensing" aria-label="Permalink to &quot;Licensing&quot;">​</a></h2><p>By submitting a contribution you agree it is licensed under Apache 2.0 (the <code>LICENSE</code> file at the repository root), and that the copyright line may carry the project&#39;s holder.</p><p>Thank you for building Open Cube OS with us.</p>`,32)])])}const m=t(n,[["render",i]]);export{p as __pageData,m as default};
